window.STUDIA_CARDS=[{"id": "kliniczna/wyklad-3-fiszki:c6e984c5", "q": "Jak Holmes i Rahe (1967) ujmują stres?", "a": "<p>Jako <strong>wydarzenia życiowe</strong> wymagające zmiany. Każde wydarzenie ma liczbę punktów, a ich suma to <strong>współczynnik zmiany życiowej</strong>.</p>", "src": "Model sytuacji stresowych"}, {"id": "kliniczna/wyklad-3-fiszki:f29052b3", "q": "Które wydarzenie ma najwyższą punktację na liście Holmesa i Rahe’a i ile punktów ma rozwód?", "a": "<p><strong>Śmierć współmałżonka</strong>: 100 pkt. Rozwód: 73 pkt.</p>", "src": "Model sytuacji stresowych"}, {"id": "kliniczna/wyklad-3-fiszki:8e8e0cb3", "q": "Czy na liście Holmesa i Rahe’a są wydarzenia przyjemne? Podaj przykłady.", "a": "<p>Tak, bo stres wywołuje sama zmiana: ślub (50), szczególne osiągnięcia osobiste (28), wakacje (13), Boże Narodzenie (12).</p>", "src": "Model sytuacji stresowych"}, {"id": "kliniczna/wyklad-3-fiszki:9373deb0", "q": "Co według slajdów zwiększa ryzyko wtórnej traumatyzacji u terapeutów i jaki jest najsilniejszy predyktor?", "a": "<p>Młodszy wiek, mniejsze doświadczenie kliniczne, negatywne doświadczenia pracy online. Najsilniejszy predyktor: <strong>satysfakcja z pracy</strong>.</p>", "src": "Model sytuacji stresowych"}, {"id": "kliniczna/wyklad-3-fiszki:d33e1f2e", "q": "Jak Lazarus i Folkman (1984) definiują stres?", "a": "<p>Jako określoną <strong>relację osoby z otoczeniem</strong>, ocenianą przez osobę jako obciążająca lub przekraczająca jej zasoby i zagrażająca jej dobrostanowi.</p>", "src": "Model transakcyjny"}, {"id": "kliniczna/wyklad-3-fiszki:df8283b7", "q": "Gdzie model transakcyjny „lokalizuje” stres?", "a": "<p>Ani w człowieku, ani w otoczeniu: stres to <strong>relacja (transakcja)</strong> między nimi.</p>", "src": "Model transakcyjny"}, {"id": "kliniczna/wyklad-3-fiszki:bbe90053", "q": "Na czym polega ocena pierwotna, a na czym wtórna?", "a": "<p><strong>Pierwotna</strong>: rozpoznanie znaczenia sytuacji jako krzywdy/straty, zagrożenia lub wyzwania. <strong>Wtórna</strong>: ocena możliwości działania (skutku dla stresora i własnych możliwości).</p>", "src": "Model transakcyjny"}, {"id": "kliniczna/wyklad-3-fiszki:2f643b17", "q": "Jakie cechy środowiska i jednostki wpływają na przebieg stresu w modelu transakcyjnym?", "a": "<p><strong>Środowisko</strong>: wsparcie społeczne emocjonalne i instrumentalne. <strong>Jednostka</strong>: cecha lęku, wzór zachowania, czynniki społeczno-demograficzne, stan zdrowia.</p>", "src": "Model transakcyjny"}, {"id": "kliniczna/wyklad-3-fiszki:3e6889e5", "q": "Jak Hobfoll definiuje stres w teorii COR?", "a": "<p>Jako wewnętrzny stan jednostki zdeterminowany percepcją <strong>zagrażającego lub zaistniałego zakłócenia równowagi</strong> w wymianie zasobów między człowiekiem a otoczeniem.</p>", "src": "Model zachowania zasobów"}, {"id": "kliniczna/wyklad-3-fiszki:09f20792", "q": "Czym są zasoby w teorii COR?", "a": "<p>Przedmioty, warunki, własności osobiste i formy energii, które są <strong>wartościowe dla przeżycia</strong> lub służą jako <strong>środek</strong> do osiągnięcia innych wartościowych celów. Celem aktywności jest ich uzyskiwanie, utrzymywanie i ochrona.</p>", "src": "Model zachowania zasobów"}, {"id": "kliniczna/wyklad-3-fiszki:d3aa4dee", "q": "Który model wnosi do definicji stresu zależność od kultury?", "a": "<p>Model Hobfolla (1989): stres zależy od kultury, w której człowiek żyje, i od wyznawanych w niej wartości.</p>", "src": "Stres: definicja łącząca modele"}, {"id": "kliniczna/wyklad-3-fiszki:1620f14e", "q": "Czym różni się radzenie sobie ze stresem od radzenia sobie z napięciem?", "a": "<p><strong>Ze stresem (coping)</strong>: aktywność wobec sytuacji stresowej. <strong>Z napięciem</strong>: techniki obniżania pobudzenia, np. oddechowe i relaksacyjne.</p>", "src": "Radzenie sobie ze stresem"}, {"id": "kliniczna/wyklad-3-fiszki:88bc88fd", "q": "Czym różnią się proces, strategia i styl radzenia sobie?", "a": "<p><strong>Proces</strong>: całość aktywności w sytuacji stresowej, dynamiczna i rozciągnięta w czasie. <strong>Strategia</strong>: ogniwo procesu. <strong>Styl</strong>: względnie stała indywidualna dyspozycja do reagowania na stres.</p>", "src": "Radzenie sobie ze stresem"}, {"id": "kliniczna/wyklad-3-fiszki:b24425c0", "q": "Jakie style radzenia sobie wyróżniają Endler i Parker (1990)?", "a": "<p>Skoncentrowany na <strong>problemie</strong> (zmiana sytuacji), na <strong>emocjach</strong> (zmiana własnego stanu) i na <strong>unikaniu</strong> (unikanie myślenia, zaprzeczanie; skuteczny dla problemów krótkotrwałych).</p>", "src": "Radzenie sobie ze stresem"}, {"id": "kliniczna/wyklad-3-fiszki:442c626b", "q": "Jakie style wyróżnia Miller (1987)?", "a": "<p>Styl <strong>konfrontacyjny</strong> (tendencja do poszukiwania informacji) i <strong>unikowy</strong> (tendencja do unikania informacji).</p>", "src": "Radzenie sobie ze stresem"}, {"id": "kliniczna/wyklad-3-fiszki:361563a9", "q": "Wymień cztery rodzaje radzenia sobie według Schwarzera i Tauberta (1999).", "a": "<p><strong>Reaktywne</strong> (kompensacja krzywdy lub straty), <strong>antycypacyjne</strong> (przyszłe wydarzenie), <strong>prewencyjne</strong> (gromadzenie zasobów), <strong>proaktywne</strong> (zdobywanie zasobów i poszukiwanie wyzwań, moderowane poczuciem własnej skuteczności).</p>", "src": "Radzenie sobie ze stresem"}, {"id": "kliniczna/wyklad-3-fiszki:9ef8eed0", "q": "Kiedy według Folkman i Moskowitz pojawia się radzenie sobie oparte na znaczeniu i co daje?", "a": "<p>Gdy rezultat jest niekorzystny i pojawia się dystres. Wywołuje emocje pozytywne, które przywracają zasoby i podtrzymują proces radzenia sobie.</p>", "src": "Radzenie sobie ze stresem"}, {"id": "kliniczna/wyklad-3-fiszki:63a9e179", "q": "Czym jest wizualizacja jako technika radzenia sobie z napięciem?", "a": "<p>Wyobrażaniem sobie miejsca lub sytuacji i jej <strong>pomyślnego zakończenia</strong>; mobilizuje organizm i nastawia możliwości psychiczne i fizyczne na realizację celu.</p>", "src": "Radzenie sobie z napięciem"}, {"id": "kliniczna/wyklad-3-fiszki:ec16cfb3", "q": "Jakie trzy nurty w opisie stresu wyróżniają Heszen-Celińska i Sęk i który dominuje?", "a": "<p>Stres jako <strong>sytuacja</strong> (bodziec), jako <strong>reakcja</strong> (stan stresu) i <strong>relacyjnie</strong> (zakłócenie lub zapowiedź zakłócenia równowagi między wymaganiami a możliwościami). Współcześnie dominuje nurt <strong>relacyjny</strong>.</p>", "src": "Psychologia zdrowia, r. 9"}, {"id": "kliniczna/wyklad-3-fiszki:da4fedc9", "q": "Jakie są trzy stadia ogólnego zespołu adaptacyjnego (GAS) Selyego?", "a": "<p>(1) <strong>reakcja alarmowa</strong> (mobilizacja sił obronnych), (2) <strong>stadium odporności</strong> (pełne przystosowanie), (3) <strong>stadium wyczerpania</strong> (gdy stresor jest silny i działa długo).</p>", "src": "Psychologia zdrowia, r. 9"}, {"id": "kliniczna/wyklad-3-fiszki:6f4cff0b", "q": "Za co krytykowano koncepcję stresu Selyego?", "a": "<p>(1) reakcje organizmu są <strong>swoiste</strong> dla czynnika szkodliwego; (2) nawet stres biologiczny zależy od <strong>czynników psychologicznych</strong>: oceny stresora, jego znaczenia i własnych możliwości.</p>", "src": "Psychologia zdrowia, r. 9"}, {"id": "kliniczna/wyklad-3-fiszki:56a42aaa", "q": "Na czym może polegać brak równowagi w ujęciu relacyjnym stresu?", "a": "<p>Na zbyt małych możliwościach wobec wymagań, ale też na <strong>zbyt małych wymaganiach</strong> wobec możliwości. Wymagania mogą być zewnętrzne lub wynikać z wewnętrznych standardów jednostki.</p>", "src": "Psychologia zdrowia, r. 9"}, {"id": "kliniczna/wyklad-3-fiszki:fc78f0d8", "q": "Jak w ocenie pierwotnej może być oceniona relacja z otoczeniem?", "a": "<p>Jako <strong>niemająca znaczenia</strong>, <strong>sprzyjająco-pozytywna</strong> albo <strong>stresująca</strong>; stresująca jako krzywda/strata, zagrożenie lub wyzwanie.</p>", "src": "Psychologia zdrowia, r. 9"}, {"id": "kliniczna/wyklad-3-fiszki:9ff9ec5e", "q": "Jakie emocje towarzyszą ocenie krzywdy/straty, zagrożenia i wyzwania?", "a": "<p><strong>Krzywda/strata</strong>: złość, żal, smutek. <strong>Zagrożenie</strong>: strach, lęk, martwienie się. <strong>Wyzwanie</strong>: negatywne jak przy zagrożeniu oraz pozytywne: nadzieja, zapał, podekscytowanie.</p>", "src": "Psychologia zdrowia, r. 9"}, {"id": "kliniczna/wyklad-3-fiszki:5c747beb", "q": "Jak ocena wtórna może wpłynąć na ocenę pierwotną?", "a": "<p>Obie oceny przebiegają równocześnie i są sprzężone: optymistyczna ocena własnych możliwości może zmienić ocenę z „zagrożenia” na „wyzwanie”, pesymistyczna odwrotnie.</p>", "src": "Psychologia zdrowia, r. 9"}, {"id": "kliniczna/wyklad-3-fiszki:814714b8", "q": "Jaka jest główna różnica między ujęciem stresu Lazarusa i Folkman a ujęciem Hobfolla?", "a": "<p>Lazarus: perspektywa <strong>indywidualistyczna</strong>, psychologia poznawcza, kryterium to <strong>subiektywna ocena</strong>. Hobfoll: perspektywa <strong>kolektywistyczna</strong>, podstawy ewolucyjne i kulturowe, kryterium to <strong>obiektywne</strong> zmiany zasobów.</p>", "src": "Psychologia zdrowia, r. 9"}, {"id": "kliniczna/wyklad-3-fiszki:67775e62", "q": "Jakie trzy okoliczności wywołują stres według Hobfolla?", "a": "<p>(1) zagrożenie utratą zasobów, (2) faktyczna utrata zasobów, (3) brak zysków po zainwestowaniu zasobów.</p>", "src": "Psychologia zdrowia, r. 9"}, {"id": "kliniczna/wyklad-3-fiszki:f4a109fa", "q": "Co to jest spirala strat i spirala zysków w teorii zachowania zasobów?", "a": "<p>Straty i zyski mają tendencję do narastania w kolejnych cyklach. <strong>Spirala strat</strong> ma większą dynamikę niż spirala zysków, a strata jest dotkliwsza niż zysk. Osoby z małymi zasobami po początkowej stracie wpadają w spiralę strat, bo nie mają czego zainwestować.</p>", "src": "Psychologia zdrowia, r. 9"}, {"id": "kliniczna/wyklad-3-fiszki:1974efc6", "q": "Jakie poziomy stresu wyróżnia Lazarus (1980) i co jest nowością tej koncepcji?", "a": "<p>Poziom <strong>społeczny</strong> (role, relacje), <strong>psychologiczny</strong> (ocena, emocje, zachowanie) i <strong>biologiczny</strong> (skutki dla organizmu). Nowość: poziomy są <strong>w dużym stopniu niezależne</strong>.</p>", "src": "Psychologia zdrowia, r. 9"}, {"id": "kliniczna/wyklad-3-fiszki:233270e4", "q": "Jak Lazarus i Folkman definiują radzenie sobie?", "a": "<p>„Stale zmieniające się poznawcze i behawioralne wysiłki mające na celu uporanie się z określonymi zewnętrznymi i wewnętrznymi wymaganiami, ocenianymi przez osobę jako obciążające lub przekraczające jej zasoby” (1984, s. 141).</p>", "src": "Psychologia zdrowia, r. 9"}, {"id": "kliniczna/wyklad-3-fiszki:4c73c706", "q": "Czy mechanizmy obronne są radzeniem sobie według Lazarusa i Folkman?", "a": "<p><strong>Tak</strong>: cel nie musi być uświadomiony, a ocena realistyczna. Wykluczone są tylko formy automatyczne bez oceny poznawczej (mechanizmy biologiczne, odruchy). Mechanizmy obronne są adaptacyjne w sytuacjach niekontrolowalnych i na początku stresu.</p>", "src": "Psychologia zdrowia, r. 9"}, {"id": "kliniczna/wyklad-3-fiszki:d17bdb76", "q": "Jakie funkcje spełnia radzenie sobie ze stresem?", "a": "<p><strong>Instrumentalna</strong> (zadaniowa, zorientowana na problem), <strong>samoregulacji emocji</strong> i, od badań Folkman, <strong>ukierunkowana na znaczenie</strong>.</p>", "src": "Psychologia zdrowia, r. 9"}, {"id": "kliniczna/wyklad-3-fiszki:1703e74e", "q": "Czym różnią się radzenie antycypacyjne, prewencyjne i proaktywne?", "a": "<p><strong>Antycypacyjne</strong>: bliskie, pewne zdarzenie z ryzykiem straty (egzamin). <strong>Prewencyjne</strong>: odległe, niepewne zagrożenia, gromadzenie zasobów (ubezpieczenie, szczepienie). <strong>Proaktywne</strong>: przyszłe wyzwania, gromadzenie zasobów na szanse (wykształcenie, zdrowy styl życia).</p>", "src": "Psychologia zdrowia, r. 9"}, {"id": "kliniczna/wyklad-3-fiszki:847e9d22", "q": "Na czym polega teoria poszerzającej i budującej roli emocji pozytywnych (Fredrickson)?", "a": "<p>Emocje pozytywne <strong>poszerzają</strong> repertuar uwagi, myślenia i działania oraz <strong>budują</strong> zasoby intelektualne i społeczne. Odwracają też fizjologiczne skutki emocji negatywnych (<em>undoing</em>).</p>", "src": "Psychologia zdrowia, r. 9"}, {"id": "kliniczna/wyklad-3-fiszki:9bfba8e9", "q": "Co wykazało badanie Gruszczyńskiej (2012) pacjentów po zawale?", "a": "<p>Strategie <strong>salutarne</strong> (wzrost emocji pozytywnych) faktycznie tłumaczyły przyrost tych emocji, a <strong>paliatywne</strong> (obniżanie negatywnych) nie redukowały afektu negatywnego, tylko mu towarzyszyły.</p>", "src": "Psychologia zdrowia, r. 9"}, {"id": "kliniczna/wyklad-3-fiszki:84911151", "q": "Czym jest zaprzeczanie chorobie i jakie ma skutki?", "a": "<p>Nieprzyjmowaniem faktu zachorowania mimo dostępnych informacji; <strong>strategia unikowa</strong>. Doraźnie chroni przed lękiem, ale na dłuższą metę bywa groźna dla życia (np. w nowotworach). Zaprzeczanie częściowe to forma radzenia opartego na znaczeniu.</p>", "src": "Psychologia zdrowia, r. 9"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:ef23ab09", "q": "Jakie dwie szerokie grupy problemów dziecięcych wyróżnia Achenbach?", "a": "<p><strong>Eksternalizacyjne</strong>: objawy skierowane na otoczenie, niedobór samokontroli (impulsywność, agresja, bunt). <strong>Internalizacyjne</strong>: objawy skierowane do wewnątrz, nadmiar kontroli z tłumieniem i zaprzeczaniem (depresja, lęk, alienacja).</p>", "src": "Psychologia kliniczna, r. 22"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:9a3fe450", "q": "Czym zajmuje się psychopatologia rozwojowa?", "a": "<p>Bada zaburzenia na tle <strong>normatywnego rozwoju</strong>: zdrowie i zaburzenie podlegają tym samym regułom, a trajektorie nie są liniowe. Kluczowe pojęcia: <strong>ekwifinalność</strong> (różne czynniki prowadzą do tego samego zaburzenia), <strong>ekwipotencjalność</strong> (ten sam układ czynników prowadzi do zdrowia albo zagrożenia), mediatory i moderatory.</p>", "src": "Psychologia kliniczna, r. 22"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:985ca6c6", "q": "Czym jest parentyfikacja?", "a": "<p>Odwróceniem ról w rodzinie: dziecko przejmuje obowiązki instrumentalne lub emocjonalne dorosłego, ponad swoje możliwości rozwojowe.</p>", "src": "Psychologia kliniczna, r. 22"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:707a1676", "q": "Jakie trzy deficyty poznawcze wyjaśniają objawy ASD?", "a": "<p>Deficyt <strong>teorii umysłu</strong>, zaburzenia <strong>funkcji wykonawczych</strong> i <strong>słaba centralna koherencja</strong> (przetwarzanie szczegółów kosztem całości).</p>", "src": "Psychologia kliniczna, r. 22"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:ee1e4d97", "q": "Jakie narzędzia są „złotym standardem” diagnozy ASD?", "a": "<p><strong>ADI-R</strong> (wywiad z rodzicem) i <strong>ADOS-2</strong> (ustrukturyzowana obserwacja dziecka).</p>", "src": "Psychologia kliniczna, r. 22"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:09f09425", "q": "Co mówi model podwójnego ryzyka w urazach czaszkowo-mózgowych u dzieci?", "a": "<p>Najgorzej rokują uszkodzenia <strong>ciężkie</strong> i <strong>wczesne</strong>. Wczesny wiek urazu nie chroni, mimo plastyczności mózgu dziecka.</p>", "src": "Psychologia kliniczna, r. 22"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:ffc2d85b", "q": "Jakie są zasady dobrej interwencji w ASD?", "a": "<p>Wczesne rozpoczęcie, rzetelny pomiar, indywidualizacja, jasne cele, co najmniej <strong>25 godzin tygodniowo</strong> we wczesnej interwencji, ciągłość, środowisko naturalne, udział i wsparcie rodziny. Przykłady podejść: <strong>ABA</strong>, <strong>model Denver</strong>, <strong>TEACCH</strong>.</p>", "src": "Psychologia kliniczna, r. 22"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:cf94c6d6", "q": "Jakie jest fundamentalne pytanie neuropsychologii klinicznej?", "a": "<p>Jaka jest istota <strong>relacji mózg–psychika (RMP)</strong>.</p>", "src": "Psychologia kliniczna, r. 23"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:a1fd6844", "q": "Czym jest neurokonektom?", "a": "<p>Strukturalnym i funkcjonalnym opisem sieci połączeń układu nerwowego (Sporns). Klasyczne ośrodki traktuje się w nim jako <strong>zasadnicze węzły</strong> sieci, a nie samodzielne „centra”.</p>", "src": "Psychologia kliniczna, r. 23"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:678979fa", "q": "Jakie trzy komponenty ma pojęcie „wybiórczości” zaburzeń neuropsychologicznych?", "a": "<p>(1) zaburzone są tylko niektóre funkcje; (2) zaburzone są tylko niektóre etapy danej funkcji; (3) zaburzone są selektywne mechanizmy mózgowe, związane z uszkodzeniem ogniskowym.</p>", "src": "Psychologia kliniczna, r. 23"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:6539fbca", "q": "Czym różni się afazja przewodzenia od afazji Wernickego?", "a": "<p>W afazji przewodzenia <strong>rozumienie jest zachowane</strong>, a zaburzone jest powtarzanie. Przyczyną jest przerwanie połączeń między ośrodkami Broki i Wernickego. W afazji Wernickego rozumienie jest zaburzone, a mowa płynna, ale zniekształcona.</p>", "src": "Psychologia kliniczna, r. 23"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:85105abe", "q": "Co to jest anozognozja?", "a": "<p>Nieświadomość własnych deficytów spowodowanych chorobą mózgu („nie wiem, że nie wiem”). Ma charakter selektywny i może współwystępować z mechanizmem zaprzeczania.</p>", "src": "Psychologia kliniczna, r. 23"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:f85be183", "q": "Na czym polega dysocjacja wiedzy jawnej i ukrytej? Podaj przykład.", "a": "<p>Zaburzona jest wiedza świadoma, a zachowana nieuświadamiana („nie wiem, że wiem”). Przykłady: pacjentka Claparède’a unikała podania ręki po ukłuciu, choć go nie pamiętała; przy prozopagnozji występuje reakcja skórno-galwaniczna na znane twarze.</p>", "src": "Psychologia kliniczna, r. 23"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:01d6be0e", "q": "Czym jest zespół zamknięcia (locked-in)?", "a": "<p>„Śpiączką rzekomą”: pacjent jest w bezruchu, ale zachowuje <strong>czuwanie i świadomość</strong>. Skala Glasgow go nie różnicuje. Komunikacja odbywa się ruchem gałek ocznych lub przez BCI.</p>", "src": "Psychologia kliniczna, r. 23"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:5af17957", "q": "Czym jest anozodiaforia?", "a": "<p>Emocjonalną obojętnością lub beztroską wobec własnych ograniczeń. Typowo pojawia się po uszkodzeniu prawej okolicy skroniowo-ciemieniowej.</p>", "src": "Psychologia kliniczna, r. 23"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:56ca1be1", "q": "Co odróżnia defekt podstawowy od objawów wtórnych w analizie syndromologicznej?", "a": "<p><strong>Defekt podstawowy</strong> (objawy pierwotne) wynika bezpośrednio z zakłócenia mechanizmu mózgowego. <strong>Objawy wtórne</strong> powstają na jego podłożu. Ustalenie obu pozwala określić syndrom (Łuria).</p>", "src": "Psychologia kliniczna, r. 23"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:885fb1d3", "q": "Jakie zasady terapii neuropsychologicznej wymienia Herzyk?", "a": "<p>Wczesne rozpoczęcie, indywidualizacja, wykorzystanie spontanicznych strategii neurokompensacyjnych, etapowość i dynamizowanie, postawa psychoterapeutyczna.</p>", "src": "Psychologia kliniczna, r. 23"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:b0412e63", "q": "Jakie dwa nurty badań ma kliniczna psychologia zdrowia?", "a": "<p><strong>Psychosomatyczny</strong> (rola czynników psychicznych w powstawaniu i przebiegu chorób) i <strong>somatopsychiczny</strong> (psychologiczne następstwa choroby).</p>", "src": "Psychologia kliniczna, r. 24"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:651f0a21", "q": "Jaką trzecią funkcję radzenia sobie dodały Folkman i Moskowitz i co ją uruchamia?", "a": "<p><strong>Radzenie sobie skoncentrowane na znaczeniu</strong>. Uruchamia je dystres po niekorzystnym wyniku transakcji. Generuje emocje pozytywne, które podtrzymują pozostałe formy radzenia sobie i odbudowują zasoby.</p>", "src": "Psychologia kliniczna, r. 24"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:0c0234f8", "q": "Jakie wyniki dały eksperymenty Cohena z wirusami przeziębienia?", "a": "<p>Zachorowało ok. <strong>25%</strong> osób mało obciążonych stresem i prawie <strong>50%</strong> najbardziej obciążonych, niezależnie od wyjściowej odporności i zachowań zdrowotnych. Ryzyko podnosiły zwłaszcza przewlekłe problemy z bliskimi i w pracy, a mediatorem były cytokiny.</p>", "src": "Psychologia kliniczna, r. 24"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:41a2a2a9", "q": "Jakie trzy fazy ma teoria adaptacji poznawczej Taylor?", "a": "<p>(1) <strong>poszukiwanie znaczenia</strong> (atrybucja przyczyn); (2) <strong>poczucie kontroli</strong>; (3) <strong>odbudowa samooceny</strong>, głównie przez porównania w dół. Teorię zbudowano na badaniu kobiet z rakiem piersi.</p>", "src": "Psychologia kliniczna, r. 24"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:e79e0427", "q": "Co wykazał eksperyment Miller i Mangana z pacjentkami przed kolposkopią?", "a": "<p>Osoby szukające informacji miały mniejsze pobudzenie, gdy dostały pełną informację. Osoby unikające miały mniejsze pobudzenie przy informacji skąpej. Interwencja powinna pasować do <strong>stylu radzenia sobie</strong>.</p>", "src": "Psychologia kliniczna, r. 24"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:5d1145b1", "q": "Czym różnią się osobowość typu C i typu D?", "a": "<p><strong>Typ C</strong>: beznadziejność, bezradność, wypieranie negatywnych emocji; wiązany z rakiem, ale słabo potwierdzony podłużnie. <strong>Typ D</strong>: negatywna emocjonalność i zahamowanie społeczne; „osobowość stresowa”, ogólny czynnik ryzyka, zwłaszcza chorób serca.</p>", "src": "Psychologia kliniczna, r. 24"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:dfeab0ff", "q": "Jakie dziedziny wzrostu potraumatycznego wyróżnili Tedeschi i Calhoun?", "a": "<p>Większa wartość życia i zmiana priorytetów, bliższe relacje, poczucie mocy osobistej, nowe możliwości, rozwój duchowy.</p>", "src": "Psychologia kliniczna, r. 24"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:6a34115a", "q": "Jak poczucie koherencji (SOC) chroni przed skutkami stresu według Antonovsky’ego?", "a": "<p>Przy silnym SOC mniej bodźców ocenia się jako stresory, częściej ocenia się je jako wyzwanie, a sięga się po lepiej dopasowane zasoby. Pomaga też ocena trzeciorzędowa, czyli korekta działań na podstawie informacji zwrotnej.</p>", "src": "Psychologia kliniczna, r. 24"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:fb696d72", "q": "Jakie trzy stopnie niepełnosprawności wyróżnia polska ustawa?", "a": "<p><strong>Znaczny</strong>: niezdolność do pracy lub praca chroniona oraz stała opieka. <strong>Umiarkowany</strong>: niezdolność do pracy lub praca chroniona oraz czasowa lub częściowa pomoc. <strong>Lekki</strong>: istotne obniżenie zdolności do pracy albo ograniczenia, które można skompensować sprzętem.</p>", "src": "Psychologia kliniczna, r. 25"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:c97208fa", "q": "Czym jest ICF i co jest w nim najważniejsze?", "a": "<p>Międzynarodową Klasyfikacją Funkcjonowania, Niepełnosprawności i Zdrowia (WHO, 2001). To nie podział osób, lecz „mapa”: uszkodzenie, dysfunkcja, czynniki środowiskowe i osobowe. Najważniejsza jest ocena <strong>aktywności i partycypacji</strong>.</p>", "src": "Psychologia kliniczna, r. 25"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:009d36d6", "q": "Jakie cztery typy cierpienia osób niepełnosprawnych opisuje Kowalik?", "a": "<p>Z dolegliwości somatycznych, z niepewności co do przyszłości, ze strat życiowych i z braku wsparcia ze strony innych.</p>", "src": "Psychologia kliniczna, r. 25"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:94f9bd28", "q": "Czym różni się indywidualny i społeczny model niepełnosprawności?", "a": "<p><strong>Indywidualny</strong>: osobista tragedia, osoba jako pacjent, kontrola ekspertów, cel to adaptacja. <strong>Społeczny</strong>: problem społeczeństwa i barier, osoba jako konsument decydujący o sobie, cel to akceptacja i zmiana postaw.</p>", "src": "Psychologia kliniczna, r. 25"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:560f426b", "q": "Czym jest ableizm (przeszacowywanie sprawności) i jakie niesie ryzyko?", "a": "<p>Zacieraniem różnic („sprawni inaczej”). Ryzyko: frustracja, zachowania niebezpieczne dla zdrowia, przemęczenie, postawa roszczeniowa, a po utracie nadziei desperacja.</p>", "src": "Psychologia kliniczna, r. 25"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:8a430dca", "q": "Dlaczego grupa może wykluczać osobę niepełnosprawną mimo formalnej integracji?", "a": "<p>Osoba ta obniża <strong>homogeniczność</strong> grupy, a grupa przywraca spójność przez wykluczenie. Formalnie osoba jest członkiem grupy, faktycznie nie uczestniczy w jej życiu.</p>", "src": "Psychologia kliniczna, r. 25"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:abae7c08", "q": "Na jakich trzech poziomach działa psycholog rehabilitacji?", "a": "<p>Jako ekspert dla polityków i władz, w pracy z grupami (rodzina, wolontariusze, grupy samopomocowe) i jako osobisty doradca osoby niepełnosprawnej.</p>", "src": "Psychologia kliniczna, r. 25"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:9564e5fb", "q": "Na czym polega teoria selektywnej optymalizacji z kompensacją?", "a": "<p>Baltesowie: <strong>selekcja</strong> to wybór ważnych celów, <strong>optymalizacja</strong> to kształtowanie korzystnych warunków, <strong>kompensacja</strong> to zastępowanie utraconych środków dostępnymi zasobami.</p>", "src": "Psychologia kliniczna, r. 26"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:166f1f6f", "q": "Co głosi teoria selektywności społeczno-emocjonalnej?", "a": "<p>Carstensen: przy krótszej perspektywie przyszłości ludzie wybierają <strong>mniej, ale głębszych</strong> relacji.</p>", "src": "Psychologia kliniczna, r. 26"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:ac550852", "q": "Które rodzaje pamięci i inteligencji słabną w starości, a które są stabilne?", "a": "<p>Słabnie pamięć epizodyczna i autobiograficzna oraz inteligencja <strong>płynna</strong>. Stabilna pozostaje pamięć proceduralna i semantyczna oraz inteligencja <strong>skrystalizowana</strong>.</p>", "src": "Psychologia kliniczna, r. 26"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:0ce42796", "q": "Jakie postawy wobec własnej starości opisał Bromley?", "a": "<p>Konstruktywną, zależności, obronną, wrogości wobec innych i autodestrukcji.</p>", "src": "Psychologia kliniczna, r. 26"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:9658e02c", "q": "Jak ICD-10 definiuje otępienie i jaki jest w nim stan świadomości?", "a": "<p>Jako przewlekły lub postępujący zespół spowodowany chorobą mózgu, z zaburzeniem pamięci, myślenia, orientacji, języka i oceny. <strong>Świadomość nie jest zaburzona</strong>.</p>", "src": "Psychologia kliniczna, r. 26"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:fd293671", "q": "Jak odróżnić depresję od otępienia u osoby starszej?", "a": "<p>Deficyty uwagi i pamięci bywają podobne. Wyraźne różnice dotyczą funkcji <strong>językowych i wzrokowo-przestrzennych</strong>, które są zaburzone w otępieniu.</p>", "src": "Psychologia kliniczna, r. 26"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:64a8d42a", "q": "Czym jest reminiscencja i jakie ma typy?", "a": "<p>Przypominaniem wydarzeń z własnego życia (Butler) dla wzmocnienia tożsamości i integracji Ja. Typy: przegląd życia, integrująca, transmisyjna, zmniejszająca znudzenie, przygotowująca do śmierci.</p>", "src": "Psychologia kliniczna, r. 26"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:bf94eff9", "q": "Czym jest ageizm i stereotyp infantylizacji?", "a": "<p><strong>Ageizm</strong> (Butler, 1969) to przedstawianie starszych jako słabych i niedołężnych. <strong>Infantylizacja</strong> to traktowanie ich jak dzieci, co sprzyja nadopiekuńczości, poczuciu bezradności i niskiej wartości.</p>", "src": "Psychologia kliniczna, r. 26"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:6b5fab54", "q": "Jak art. 31 § 1 k.k. definiuje niepoczytalność i jaką metodą?", "a": "<p>Sprawca z powodu choroby psychicznej, upośledzenia umysłowego lub innego zakłócenia czynności psychicznych nie mógł w czasie czynu rozpoznać jego znaczenia lub pokierować swoim postępowaniem. To <strong>metoda mieszana</strong>: przyczyna psychiatryczna musi dawać skutek psychologiczny.</p>", "src": "Psychologia kliniczna, r. 27"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:d02a0da8", "q": "Czym różni się silne wzburzenie z art. 148 § 4 k.k. od afektu z art. 31 § 2 k.k.?", "a": "<p>Art. 148 § 4: wzburzenie <strong>usprawiedliwione okolicznościami</strong>, wywołane czynnikami zewnętrznymi, o charakterze sytuacyjnym. Art. 31 § 2: ograniczona poczytalność, w której ważniejsze są czynniki wewnętrzne sprawcy.</p>", "src": "Psychologia kliniczna, r. 27"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:6119f3ed", "q": "Jakie trzy warianty biegłych przewiduje prawo?", "a": "<p>Biegły <strong>z listy</strong> (prezes sądu okręgowego, kadencja 5 lat), biegły <strong>ad hoc</strong> (do konkretnej sprawy) i biegły <strong>instytucjonalny</strong> (opinia instytucji naukowej lub specjalistycznej).</p>", "src": "Psychologia kliniczna, r. 27"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:abeeea78", "q": "Jaki próg rzetelności testu podają kryteria Heilbruna?", "a": "<p><strong>0,80 i więcej</strong>. Użycie mniej rzetelnego testu biegły musi uzasadnić.</p>", "src": "Psychologia kliniczna, r. 27"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:b5230bcb", "q": "Jak psychologia ujmuje prawne pojęcie demoralizacji nieletnich?", "a": "<p>Ustawa go nie definiuje, tylko wymienia przejawy. Odpowiednikami psychologicznymi są <strong>niedostosowanie społeczne</strong> i <strong>asocjalność</strong> (Stanik).</p>", "src": "Psychologia kliniczna, r. 27"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:c0c23581", "q": "Co głosi ogólna teoria napięcia Agnew?", "a": "<p>Niepowodzenie w osiąganiu celów, utrata bodźców pozytywnych i narażenie na negatywne wzbudzają afekt negatywny. Przestępstwo jest sposobem zlikwidowania napięcia. Teoria wyjaśnia zarówno pojedynczy czyn (czynnik spustowy), jak i przestępczość (predyspozycja).</p>", "src": "Psychologia kliniczna, r. 27"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:3bba1dc7", "q": "Na jakim założeniu opiera się profilowanie i która hipoteza ma najlepsze poparcie?", "a": "<p>Na <strong>stałości transsytuacyjnej</strong> zachowania. Najlepiej popartą hipotezą jest <strong>stałość przestępcy</strong> (Canter). Homologia (podobne zachowania oznaczają podobnych sprawców) ma słabsze poparcie.</p>", "src": "Psychologia kliniczna, r. 27"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:719ffc5f", "q": "Co mówi zasada dostatecznej racji i zasada selektywności informacji w psychologii sądowej?", "a": "<p><strong>Dostateczna racja</strong>: dystans poznawczy i sądy opisowe zamiast oceniających. <strong>Selektywność</strong>: w opinii tylko informacje niezbędne dla organu procesowego.</p>", "src": "Psychologia kliniczna, r. 27"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:efe5cdb1", "q": "Czym różni się relacja biegłego z badanym od relacji terapeuty z pacjentem?", "a": "<p>Klientem biegłego jest sąd lub strona, nie badany. Postawa biegłego jest neutralna i oceniająca, dane weryfikuje się z wielu źródeł, strukturę narzuca biegły, a antagonizm jest częsty. Celem jest ocena, nie pomoc.</p>", "src": "Psychologia kliniczna, r. 27"}, {"id": "kliniczna/wyklad-2-dziedziny-fiszki:024978e3", "q": "Jakie trzy rodzaje diagnoz wyróżnia się w psychologii penitencjarnej?", "a": "<p><strong>Resocjalizacyjną</strong> (nieprzystosowanie i podatność na oddziaływania), <strong>terapeutyczną</strong> (zaburzenia w trakcie kary) i <strong>ryzyka recydywy</strong> (Niewiadomska).</p>", "src": "Psychologia kliniczna, r. 27"}, {"id": "kliniczna/fiszki:16ab24f9", "q": "Wymień siedem kryteriów poziomu naukowości teorii (McAdams, 1994).", "a": "<p>Wszechstronność, prostota, spójność, testowalność, trafność empiryczna, użyteczność, twórczość.</p>", "src": "Podstawy teoretyczne i patogeneza/salutogeneza"}, {"id": "kliniczna/fiszki:5180c328", "q": "Czym różni się model nominalny od modelu realnego?", "a": "<p>Model nominalny to teoretyczny sposób rozumienia zjawiska, niekoniecznie zweryfikowany empirycznie; model realny został sprawdzony (w całości lub części) w badaniach empirycznych — przykładem jest model salutogenezy Antonovsky'ego.</p>", "src": "Podstawy teoretyczne i patogeneza/salutogeneza"}, {"id": "kliniczna/fiszki:67586125", "q": "Jakie cztery kategorie czynników patogennych wyodrębnia się w psychopatologii?", "a": "<p>Psychogenne, egzogenne, somatogenne, endogenne (Sęk, 2008b).</p>", "src": "Podstawy teoretyczne i patogeneza/salutogeneza"}, {"id": "kliniczna/fiszki:514622f8", "q": "Jakie pytanie postawił Aaron Antonovsky, które dało początek modelowi salutogenezy?", "a": "<p>„Dlaczego ludzie, mimo oddziaływania wielu stresorów (patogenów), zachowują zdrowie lub w razie choroby szybko do niego powracają?” — sformułowane po zaobserwowaniu, że 29% kobiet, które przeżyły ekstremalny stres (np. obóz koncentracyjny), zachowało dobry stan zdrowia.</p>", "src": "Podstawy teoretyczne i patogeneza/salutogeneza"}, {"id": "kliniczna/fiszki:1860e234", "q": "Z jakich trzech komponentów składa się poczucie koherencji (SOC)?", "a": "<p>Poczucie zrozumiałości (komponent poznawczy), poczucie zaradności/sterowalności (komponent instrumentalny) i poczucie sensowności (komponent motywacyjno-emocjonalny — uznawany za najważniejszy).</p>", "src": "Podstawy teoretyczne i patogeneza/salutogeneza"}, {"id": "kliniczna/fiszki:ddcdfd1e", "q": "Na czym polega komplementarność podejścia patogenetycznego i salutogenetycznego?", "a": "<p>Oba podejścia nie są konkurencyjne — patogeneza wyjaśnia przyczyny choroby (patogeny, stresory, podatność), salutogeneza wyjaśnia utrzymanie i odzyskiwanie zdrowia (zasoby, SOC). Łączne stosowanie obu perspektyw daje pełniejszy obraz zdrowia i choroby jako interakcji czynników ryzyka i zasobów.</p>", "src": "Podstawy teoretyczne i patogeneza/salutogeneza"}, {"id": "kliniczna/fiszki:50fd285f", "q": "Jak WHO zdefiniowała zdrowie w 1946 r.?", "a": "<p>Jako pełny dobrostan fizyczny (well-being), psychiczny i społeczny, a nie tylko brak choroby lub niepełnosprawności.</p>", "src": "Pojęcie zdrowia"}, {"id": "kliniczna/fiszki:a8c63171", "q": "Jaki jest związek między zdrowiem duchowym a zdrowiem somatycznym?", "a": "<p>Duchowość jako dyspozycja może rozwijać się w ciągu całego życia, także w podeszłym wieku; poważna choroba somatyczna (zwłaszcza zagrażająca życiu) i związane z nią doświadczenia mogą przyspieszać rozwój duchowy (potraumatyczny wzrost).</p>", "src": "Pojęcie zdrowia"}, {"id": "kliniczna/fiszki:c2b3ef93", "q": "Jaka jest relacja między pojęciem zdrowia a pojęciem szczęścia wg Władysława Tatarkiewicza?", "a": "<p>Zdrowie i szczęście nie są tożsame, ale są bardzo podobne w formalnej strukturze — oba wielowymiarowe, oba pojmowane jako stan przejściowy lub stały układ czynności. Zdrowie to jedno z dóbr człowieka, ale nie jedyne.</p>", "src": "Pojęcie zdrowia"}, {"id": "kliniczna/fiszki:adf82a44", "q": "Jaka jest relacja między pojęciem zdrowia a pojęciem jakości życia?", "a": "<p>Jakość życia ma szerszy zakres pojęciowy niż zdrowie — obejmuje warunki ekonomiczne, społeczne i medyczne. Zdrowie jest jednym z wyznaczników (obiektywnych i subiektywnych) jakości życia, a nie pojęciem tożsamym.</p>", "src": "Pojęcie zdrowia"}, {"id": "kliniczna/fiszki:d83b41dc", "q": "Na czym polega dualistyczne podejście do ciała i psychiki w modelu biomedycznym?", "a": "<p>Wywodzi się z założenia kartezjańskiego — ciało i psychika są odrębnymi bytami; ciało traktowane jest jak maszyna, a zdrowie i choroba są kategoriami rozłącznymi.</p>", "src": "Modele zdrowia"}, {"id": "kliniczna/fiszki:08a92b7a", "q": "Dlaczego model biomedyczny okazał się niewystarczający do zrozumienia zdrowia i choroby?", "a": "<p>Jest redukcjonistyczny — koncentruje się wyłącznie na czynnikach biologicznych, pomija rolę psychiki, kontekstu społecznego i aktywności własnej pacjenta; dowody kliniczne pokazały, że objawy cielesne mogą wynikać z nierozwiązanych konfliktów psychologicznych.</p>", "src": "Modele zdrowia"}, {"id": "kliniczna/fiszki:4b61f72a", "q": "Jakie są główne założenia modelu biopsychospołecznego G. Engla?", "a": "<p>Zdrowie i choroba to system interakcji czynników biologicznych, psychologicznych i społecznych; przyjmuje stanowisko holistyczne — ciało i psychika stanowią integralną całość; pełne zrozumienie choroby wymaga uwzględnienia kontekstu życia pacjenta.</p>", "src": "Modele zdrowia"}, {"id": "kliniczna/fiszki:9f4272c8", "q": "Co nowego wprowadził model socjoekologiczny w porównaniu z wcześniejszymi modelami?", "a": "<p>Wprowadził bardziej złożony, hierarchiczny układ systemów („pola zdrowia” wg Lalonde'a) oraz metaforę mandali — z człowiekiem w centrum, otoczonym coraz szerszymi kręgami wpływu (styl życia, środowisko, kultura, biosfera), z rodziną jako ogniwem pośredniczącym.</p>", "src": "Modele zdrowia"}, {"id": "kliniczna/fiszki:7e76301c", "q": "Na czym polega zdrowie psychiczne w modelu dobrostanu psychicznego Ryff?", "a": "<p>To sześć komponentów: samoakceptacja, pozytywne relacje z ludźmi, autonomia, radzenie sobie z otoczeniem, cel życiowy, osobisty rozwój — wywodzących się z filozoficznej tradycji eudajmonii Arystotelesa i klasycznych koncepcji osobowości (Allport, Jung, Jahoda, Frankl, Maslow, Erikson, Rogers).</p>", "src": "Modele zdrowia"}, {"id": "kliniczna/fiszki:84b98625", "q": "Ile procent współprzyczyn chorób chronicznych i zgonów przypisuje się czynnikom psychologicznym?", "a": "<p>Ok. 50% (Sęk, Heszen, 2020).</p>", "src": "Treści z wykładu"}, {"id": "kliniczna/fiszki:ae493b3a", "q": "Wymień sześć tez modelu biomedycznego (BMM).", "a": "<p>1) Choroby mają źródło w nieprawidłowościach struktur ciała. 2) Choroba powoduje symptomy, niezwiązane z czynnikami zewnętrznymi. 3) Zdrowie = brak choroby. 4) Zjawiska psychiczne nie są związane z funkcjami ciała. 5) Pacjent jest „ofiarą nieszczęśliwego trafu”. 6) Pacjent ma być w pełni gotowy do wypełniania zaleceń profesjonalistów.</p>", "src": "Treści z wykładu"}, {"id": "kliniczna/fiszki:5431f56a", "q": "Na czym opiera się model biopsychospołeczny pod względem metodologicznym?", "a": "<p>Na ogólnej teorii systemów Bertalanffy'ego (1968) — zjawiska naturalne tworzą hierarchię systemów, z których każdy jest jednocześnie częścią systemu większego i zbiorem systemów podrzędnych (od cząsteczki po biosferę), a osoba/pacjent zajmuje w tej hierarchii centralne miejsce.</p>", "src": "Treści z wykładu"}, {"id": "kliniczna/fiszki:121c7d8b", "q": "Czym różni się rozumienie „patologii” od „choroby” w ujęciu BPSM?", "a": "<p>Patologia („proces chorobowy”) wymaga diagnozy biomedycznej i dotyczy narządu lub układu. Choroba dotyka całego człowieka, jego najbliższe otoczenie i grupę społeczną.</p>", "src": "Treści z wykładu"}, {"id": "kliniczna/fiszki:3027dfa4", "q": "Jakie są trzy cechy modelu konsumeryckiego w opiece zdrowotnej?", "a": "<p>Pacjent jako klient odpowiedzialny za własne zdrowie; podkreślenie znaczenia jego wyborów; opieka zdrowotna traktowana jak usługa rynkowa, z naciskiem na satysfakcję klienta.</p>", "src": "Treści z wykładu"}, {"id": "kliniczna/fiszki:95e9b623", "q": "Jaki jest paradoks w tym, jak podejście patogenetyczne i salutogenetyczne definiują „normalny stan organizmu”?", "a": "<p>Podejście patogenetyczne zakłada, że normalnym stanem jest homeostaza (zakłócana przez stresory), natomiast podejście salutogenetyczne zakłada, że normalnym stanem organizmu jest nieporządek/zakłócenie homeostazy, a zdrowie to nieustanny, dynamiczny proces radzenia sobie z tym stanem.</p>", "src": "Treści z wykładu"}, {"id": "kliniczna/fiszki:70e84311", "q": "Jakie trzy elementy mają kluczowe znaczenie w procesie osiągania zdrowia wg Antonovsky'ego?", "a": "<p>Rodzaje i poziom stresów, uogólnione zasoby odpornościowe oraz poczucie koherencji.</p>", "src": "Treści z wykładu"}, {"id": "kliniczna/fiszki:6300a409", "q": "Wymień trzy cele strategii WHO „Health for all”.", "a": "<p>Dodanie lat do życia, dodanie zdrowia do życia (wellbeing), dodanie życia do lat (sens życia, productive life).</p>", "src": "Treści z wykładu"}, {"id": "kliniczna/fiszki:d83c2fc0", "q": "Jaki wymiar zdrowia dodaje wykład do klasycznych czterech dziedzin (fizyczne, psychiczne, społeczne, duchowe)?", "a": "<p>Zdrowie seksualne — zespół biologicznych, emocjonalnych, intelektualnych i społecznych aspektów życia seksualnego (WHO, 2001). Wykład dzieli też zdrowie psychiczne na składową umysłową i emocjonalną.</p>", "src": "Treści z wykładu"}, {"id": "kliniczna/fiszki:171d1f90", "q": "Wymień pięć obszarów zainteresowań psychologii zdrowia wg wykładu.", "a": "<p>Promowanie zdrowego stylu życia; metody leczenia chorób i zapobieganie chorobom; badania nad czynnikami ryzyka i czynnikami chroniącymi; analiza systemów opieki zdrowotnej; formułowanie polityki zdrowotnej.</p>", "src": "Zastosowania, prewencja i relacja pacjent–system (treści z wykładu)"}, {"id": "kliniczna/fiszki:97f7b30f", "q": "Czym różnią się dwie definicje stylu życia przytoczone na wykładzie?", "a": "<p>Pierwsza (Sęk, Heszen, 2020) akcentuje wymiar społeczno-strukturalny — styl życia jako odzwierciedlenie przynależności do warstwy społecznej i wzorów kulturowych. Druga (Sęk, 2000) akcentuje wymiar indywidualno-psychologiczny — system zachowań zdrowotnych uwarunkowany temperamentem, wiedzą, przekonaniami, kompetencjami i wartościami jednostki.</p>", "src": "Zastosowania, prewencja i relacja pacjent–system (treści z wykładu)"}, {"id": "kliniczna/fiszki:26578156", "q": "Jakie są dwa rodzaje zachowań zdrowotnych?", "a": "<p>Nawykowe, stabilne wzory zachowań (np. higiena, nawyki żywieniowe) oraz celowe czynności zdrowotne (np. przygotowanie do ciąży, podejmowanie leczenia).</p>", "src": "Zastosowania, prewencja i relacja pacjent–system (treści z wykładu)"}, {"id": "kliniczna/fiszki:c8808cef", "q": "O ile lat dłużej żyją osoby stosujące pięć zdrowych nawyków, wg badań Harvardu?", "a": "<p>Średnio 14 lat dłużej (Li i in., 2018).</p>", "src": "Zastosowania, prewencja i relacja pacjent–system (treści z wykładu)"}, {"id": "kliniczna/fiszki:eba74334", "q": "Jakie dwie klasyfikacje prewencji omówiono na wykładzie?", "a": "<p>Klasyfikacja wg poziomów (WHO: pierwszorzędowa, drugorzędowa, trzeciorzędowa) oraz wg odbiorców (uniwersalna, selektywna, wskazująca).</p>", "src": "Zastosowania, prewencja i relacja pacjent–system (treści z wykładu)"}, {"id": "kliniczna/fiszki:ed24160d", "q": "Jakie wyzwania stoją przed pacjentem w okresie hospitalizacji?", "a": "<p>Problemy domowe, lęk przed poważną chorobą/obawa związana z operacją, nieznane otoczenie, utrata godności, utrata kontroli, brak wsparcia.</p>", "src": "Zastosowania, prewencja i relacja pacjent–system (treści z wykładu)"}, {"id": "kliniczna/fiszki:d5eca8a8", "q": "Czym różni się oddziaływanie instrumentalne od ekspresywnego w relacji terapeutycznej?", "a": "<p>Oddziaływanie instrumentalne to czynności ściśle związane z leczeniem; oddziaływanie ekspresywne to czynności zaspokajające potrzeby psychologiczne pacjenta.</p>", "src": "Zastosowania, prewencja i relacja pacjent–system (treści z wykładu)"}, {"id": "kliniczna/fiszki:86234826", "q": "Co wynika z badania Browna i in. (2009) nad lekarzami przekazującymi trudne informacje?", "a": "<p>Wyższy fizjologiczny poziom stresu występował u lekarzy z mniejszym doświadczeniem zawodowym i wyższym poziomem zmęczenia; słabsza efektywność komunikacji wiązała się z wyższym wypaleniem zawodowym i zmęczeniem.</p>", "src": "Zastosowania, prewencja i relacja pacjent–system (treści z wykładu)"}, {"id": "kliniczna/fiszki:5192a541", "q": "Z jakich trzech poziomów składa się reakcja na stres?", "a": "<p>Poziom fizjologiczny, poziom psychologiczny (emocje i procesy poznawcze) oraz poziom zachowania.</p>", "src": "Zastosowania, prewencja i relacja pacjent–system (treści z wykładu)"}, {"id": "kliniczna/fiszki:dc1141eb", "q": "Czym różni się ocena pierwotna od oceny wtórnej w modelu Lazarusa i Folkman?", "a": "<p>Ocena pierwotna to rozpoznanie znaczenia sytuacji (krzywda/strata, zagrożenie, wyzwanie); ocena wtórna to ocena własnych możliwości działania i potencjalnego efektu dla źródła stresu. Oba procesy są ze sobą sprzężone.</p>", "src": "Zastosowania, prewencja i relacja pacjent–system (treści z wykładu)"}, {"id": "kliniczna/fiszki:0fe5536a", "q": "Jakie trzy sposoby definiowania zachowań zdrowotnych wyróżnia się w literaturze?", "a": "<p>Definicję skutkową/funkcjonalną (funkcja zachowania względem zdrowia), definicję celowościową (czynności celowo ukierunkowane na zdrowie) oraz definicję celowościowo-funkcjonalną, łączącą oba podejścia (Puchalski, 1990).</p>", "src": "Treści z literatury (Heszen, Sęk, 2007)"}, {"id": "kliniczna/fiszki:266d78d4", "q": "Co wykazały badania Alameda Study (1965–1983) i dlaczego nazywa się je „drugą rewolucją zdrowotną”?", "a": "<p>Wykazały, że niepalenie, umiarkowane picie alkoholu, utrzymywanie właściwej masy ciała, aktywność ruchowa i 7–8 godzin snu pozytywnie korelują ze stanem zdrowia aktualnym i przewidywanym. Nazwę „druga rewolucja zdrowotna” nadał temu etapowi Gniazdowski (1990), bo przesunął on uwagę badaczy z czynników biomedycznych na behawioralne.</p>", "src": "Treści z literatury (Heszen, Sęk, 2007)"}, {"id": "kliniczna/fiszki:bfce8315", "q": "Jaka jest różnica między behawioralno-epidemiologicznym a socjologicznym ujęciem stylu życia?", "a": "<p>Ujęcie behawioralno-epidemiologiczne traktuje styl życia czysto behawioralnie — jako zespół zachowań ustalany na podstawie obiektywnych badań prospektywnych (np. raport Lalonde'a). Ujęcie socjologiczne traktuje styl życia jako znacznie bardziej złożony — odzwierciedlenie przynależności do warstwy społecznej i wzorów kulturowych, z coraz większym naciskiem na indywidualne wybory.</p>", "src": "Treści z literatury (Heszen, Sęk, 2007)"}, {"id": "kliniczna/fiszki:417c57b3", "q": "Jakie trzy czynniki wyłoniła analiza czynnikowa kwestionariusza zachowań zdrowotnych Beckera (1992)?", "a": "<p>Zachowania prewencyjne (dostosowane do norm i oczekiwań), zdrową dietę i ruch, oraz relaks/odpoczynek/higienę psychiczną.</p>", "src": "Treści z literatury (Heszen, Sęk, 2007)"}, {"id": "kliniczna/fiszki:8cab74c3", "q": "Na czym polegał ogólny zespół adaptacyjny (GAS) opisany przez Hansa Selyego i jakie ma trzy stadia?", "a": "<p>To niespecyficzna reakcja organizmu na działanie stresorów, obejmująca: stadium reakcji alarmowej (mobilizacja sił obronnych), stadium odporności (pełne przystosowanie) i stadium wyczerpania (gdy stresor działa odpowiednio długo i intensywnie).</p>", "src": "Treści z literatury (Heszen, Sęk, 2007)"}, {"id": "kliniczna/fiszki:3a37ddf1", "q": "Jakie emocje towarzyszą ocenie pierwotnej typu „wyzwanie” w modelu Lazarusa i Folkman, i czym różnią się od emocji przy „zagrożeniu”?", "a": "<p>Przy wyzwaniu obraz emocjonalny jest najbardziej złożony — obejmuje zarówno emocje negatywne (podobne jak przy zagrożeniu: lęk, obawa), jak i pozytywne: nadzieję, zapał, podniecenie. Przy samym zagrożeniu dominują wyłącznie emocje negatywne: strach, lęk, martwienie się.</p>", "src": "Treści z literatury (Heszen, Sęk, 2007)"}, {"id": "kliniczna/fiszki:74b5a1a8", "q": "Kto jest autorem pierwszej definicji psychologii zdrowia i co ona obejmuje?", "a": "<p><strong>Joseph Matarazzo</strong> (1980): oświatowy, naukowy i profesjonalny wkład psychologii do promocji i utrzymywania zdrowia, zapobiegania chorobom i ich leczenia, rozpoznawania etiologicznych i diagnostycznych korelatów zdrowia i choroby; w 1982 r. dodał analizę i ulepszanie systemu opieki zdrowotnej oraz kształtowanie polityki zdrowotnej.</p>", "src": "Zastosowania · Heszen-Celińska, Sęk (2020), r. 2"}, {"id": "kliniczna/fiszki:c74e3509", "q": "Co odróżnia psychologię zdrowia od medycyny psychosomatycznej, behawioralnej i psychologii medycznej?", "a": "<p>W centrum jest <strong>zdrowie</strong>, nie choroba, a zakres wykracza poza medycynę na wszystkie dziedziny życia i systemy społeczne (rodzina, szkoła, praca). Wcześniejsze kierunki skupiały się na zdrowiu fizycznym i chorobie somatycznej.</p>", "src": "Zastosowania · Heszen-Celińska, Sęk (2020), r. 2"}, {"id": "kliniczna/fiszki:b4d5421c", "q": "Dlaczego laboratoryjne badania podstawowe słabo nadają się do zastosowań w zdrowiu i chorobie?", "a": "<p>Nie da się odtworzyć ważnych zdarzeń życiowych; ograniczenia etyczne (zwłaszcza u chorych); czynnik czasu (skutki zdrowotne pojawiają się późno); czynnik kontroli: eliminacja zmiennych zakłócających obniża <strong>trafność zewnętrzną (ekologiczną)</strong>.</p>", "src": "Zastosowania · Heszen-Celińska, Sęk (2020), r. 2"}, {"id": "kliniczna/fiszki:e9c4ace9", "q": "Jaki jest obszar zainteresowania klinicznej psychologii zdrowia?", "a": "<p>Psychologiczne aspekty chorób; centrum działań to <strong>człowiek chory</strong>. Dwa nurty: <strong>psychosomatyczny</strong> (rola czynników psychicznych w chorobie) i <strong>somatopsychiczny</strong> (psychologiczne następstwa choroby).</p>", "src": "Zastosowania · Heszen-Celińska, Sęk (2020), r. 2"}, {"id": "kliniczna/fiszki:ea8d3c23", "q": "Jaki jest obszar zainteresowania pozytywnej psychologii zdrowia?", "a": "<p>Psychologiczne uwarunkowania i korelaty zdrowia oraz oddziaływania na <strong>ludzi zdrowych</strong>; obiecujące jest podejście <strong>salutogenetyczne</strong>. Jej główne zadanie praktyczne to <strong>promocja zdrowia</strong>.</p>", "src": "Zastosowania · Heszen-Celińska, Sęk (2020), r. 2"}, {"id": "kliniczna/fiszki:b84aa6b8", "q": "Czym różni się podejście psychologa i lekarza do pacjenta według Heszen-Celińskiej i Sęk?", "a": "<p>Psycholog traktuje człowieka jako <strong>podmiot</strong> z prawem do decyzji i odpowiedzialnością za ich skutki; lekarze oczekują raczej <strong>podporządkowania</strong>, a odpowiedzialność deleguje się na lekarza.</p>", "src": "Zastosowania · Heszen-Celińska, Sęk (2020), r. 2"}, {"id": "kliniczna/fiszki:f29d016c", "q": "Jakie okoliczności zadecydowały o uznaniu psychologii zdrowia za odrębną dziedzinę?", "a": "<p>Sekcja Psychologii Zdrowia APA (1978), czasopismo <em>Health Psychology</em> (1982), sekcja w IAAP (1984), EHPS i <em>Psychology and Health</em> (1986), programy akademickie i jednostki na uczelniach.</p>", "src": "Zastosowania · Heszen-Celińska, Sęk (2020), r. 2"}, {"id": "kliniczna/fiszki:05013c1f", "q": "Czy psychologia zdrowia to dział psychologii stosowanej, czy odrębna dziedzina? Jakie są stanowiska?", "a": "<p>Matarazzo (1987): obszar zastosowań podstawowej dyscypliny. Taylor (1990): odrębna dziedzina nauki, bo włącza wiedzę interdyscyplinarną. Autorki podręcznika: spełnia kryteria <strong>odrębnej dziedziny stosowanej</strong>.</p>", "src": "Zastosowania · Heszen-Celińska, Sęk (2020), r. 2"}, {"id": "kliniczna/fiszki:626eb2ed", "q": "Jakie trzy typy diagnozy klinicznej wyróżniają Cierpiałkowska, Soroko i Sęk?", "a": "<p><strong>Różnicową</strong> (opisową, nozologiczną), <strong>strukturalno-funkcjonalną</strong> i <strong>genetyczną</strong> (statyczną i rozwojową). Pierwsza ma charakter opisowy, dwie pozostałe wyjaśniający.</p>", "src": "Zastosowania · Cierpiałkowska, Sęk (2016), r. 10"}, {"id": "kliniczna/fiszki:bbf94844", "q": "Jakie są cztery funkcje diagnozowania?", "a": "<p><strong>Opisująca i oceniająca</strong> (jaka jest rzeczywistość), <strong>eksplanacyjna</strong> (dlaczego taka jest), <strong>predykcyjna</strong> (jaka będzie), <strong>korekcyjna/terapeutyczna</strong> (co zrobić, by osiągnąć pożądany stan).</p>", "src": "Zastosowania · Cierpiałkowska, Sęk (2016), r. 10"}, {"id": "kliniczna/fiszki:733bbadc", "q": "Czym jest kontrakt diagnostyczny?", "a": "<p>Umową między psychologiem a osobą lub grupą, która zgadza się wykonać zadania będące podstawą oceny jej funkcjonowania; poprzedza działania diagnostyczne.</p>", "src": "Zastosowania · Cierpiałkowska, Sęk (2016), r. 10"}, {"id": "kliniczna/fiszki:9954a5f8", "q": "Na czym polega diagnoza różnicowa (nozologiczna)?", "a": "<p>Na rozpoznaniu symptomów (znaczących klinicznie doświadczeń i zachowań) i odniesieniu ich do jednostek z ICD-10 lub DSM-5; o hipotezie decyduje stopień podobieństwa objawów, ich liczba i czas trwania.</p>", "src": "Zastosowania · Cierpiałkowska, Sęk (2016), r. 10"}, {"id": "kliniczna/fiszki:3ae413a4", "q": "Czym jest podwójna diagnoza?", "a": "<p>Rozpoznaniem więcej niż jednego zaburzenia u osoby, np. osobowości zależnej i lęku uogólnionego u pani Marty. Współwystępowanie zaburzeń osi I z zaburzeniami osobowości wymaga leczenia skojarzonego.</p>", "src": "Zastosowania · Cierpiałkowska, Sęk (2016), r. 10"}, {"id": "kliniczna/fiszki:00876685", "q": "Czego dotyczy diagnoza strukturalno-funkcjonalna?", "a": "<p>Wyjaśnienia, jaki <strong>patomechanizm</strong> leży u podłoża symptomów, jakie czynniki go aktywują oraz jakie <strong>mechanizmy salutogenetyczne</strong> są obecne; odwołuje się do konkretnej koncepcji psychologicznej.</p>", "src": "Zastosowania · Cierpiałkowska, Sęk (2016), r. 10"}, {"id": "kliniczna/fiszki:a3f988a8", "q": "Jakie aspekty osobowości ocenia psychodynamiczna diagnoza strukturalno-funkcjonalna?", "a": "<p>Poczucie tożsamości, mechanizmy obronne, testowanie rzeczywistości, relacje z obiektem, funkcjonowanie moralne; na tej podstawie ocenia się poziom organizacji osobowości: psychotyczny, borderline lub neurotyczny.</p>", "src": "Zastosowania · Cierpiałkowska, Sęk (2016), r. 10"}, {"id": "kliniczna/fiszki:08b03820", "q": "Jakie elementy obejmuje poznawczo-behawioralna konceptualizacja przypadku?", "a": "<p>Przekonania kluczowe (schematy), przekonania pośredniczące (założenia, postawy, zasady), myśli automatyczne, sytuacje aktywujące i zniekształcenia poznawcze podtrzymujące schemat.</p>", "src": "Zastosowania · Cierpiałkowska, Sęk (2016), r. 10"}, {"id": "kliniczna/fiszki:3035d5a5", "q": "Dlaczego Rogers krytykował formułowanie diagnozy i kiedy dopuszcza się ją w podejściu skoncentrowanym na osobie?", "a": "<p>Bo stwarza <strong>nierównowagę władzy</strong> i niezdrową zależność od terapeuty-eksperta. Dopuszcza się ją, gdy klient sobie tego życzy, gdy wymaga tego instytucja lub gdy potrzebne są obiektywne pomiary; ma być wspólną aktywnością terapeuty i klienta.</p>", "src": "Zastosowania · Cierpiałkowska, Sęk (2016), r. 10"}, {"id": "kliniczna/fiszki:34b691e1", "q": "Czym różni się diagnoza epigenetyczna aktualnej struktury od rozwojowej?", "a": "<p><strong>Aktualna</strong>: udział czynników konstytucyjnych, sytuacyjnych i psychicznych w chwili zgłoszenia. <strong>Rozwojowa</strong>: udział tych czynników w zaburzeniu na kolejnych etapach życia.</p>", "src": "Zastosowania · Cierpiałkowska, Sęk (2016), r. 10"}, {"id": "kliniczna/fiszki:958d51a1", "q": "Jakie założenia przyjmuje model wielościeżkowy (Sue, Sue i Sue)?", "a": "<p>Żadna perspektywa nie wystarcza; istnieją różne drogi do zaburzeń; czynniki przyczyniają się w różnym stopniu; wiedza opiera się na badaniach; czynniki są w ciągłej interakcji, więc te same mogą prowadzić do różnych zaburzeń, a różne do podobnych.</p>", "src": "Zastosowania · Cierpiałkowska, Sęk (2016), r. 10"}, {"id": "kliniczna/fiszki:2acb6721", "q": "Czym jest diagnoza prospektywna w psychoterapii?", "a": "<p>Diagnozowaniem w trakcie terapii tego, jakie procedury i strategie zastosować; obok niej diagnozuje się mechanizm zmiany (jak działają) i jej skutki (diagnoza strukturalno-funkcjonalna).</p>", "src": "Zastosowania · Cierpiałkowska, Sęk (2016), r. 10"}];
